<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../config/db.php';
if(!hasModulePermission('staff','create')){http_response_code(403);exit('You do not have permission to create staff profiles.');}
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location:index.php');exit;}verify_csrf();
try{$name=trim((string)($_POST['full_name']??''));$phone=trim((string)($_POST['phone']??''));$email=trim((string)($_POST['email']??''));$dept=trim((string)($_POST['department']??''));$title=trim((string)($_POST['job_title']??''));$type=(string)($_POST['employment_type']??'Full-time');$date=trim((string)($_POST['hire_date']??''));$status=(string)($_POST['status']??'Active');$notes=trim((string)($_POST['notes']??''));if($name==='')throw new RuntimeException('Full name is required.');if(!in_array($type,['Full-time','Part-time','Casual','Contract'],true))throw new RuntimeException('Invalid employment type.');if(!in_array($status,['Active','Inactive','Terminated'],true))throw new RuntimeException('Invalid staff status.');if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid email address.');$prefix='EMP';$q=$conn->query("SELECT setting_value FROM settings WHERE setting_key='employee_prefix' LIMIT 1");$v=$q->fetchColumn();if($v)$prefix=(string)$v;$number=$prefix.'-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(2)));$q=$conn->prepare("INSERT INTO staff(employee_number,full_name,email,phone,department,job_title,employment_type,hire_date,status,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)");$q->execute([$number,$name,$email?:null,$phone?:null,$dept?:null,$title?:null,$type,$date?:null,$status,$notes?:null,(int)$_SESSION['user_id']]);$_SESSION['staff_flash']='Staff profile '.$number.' created successfully.';}catch(Throwable $e){$_SESSION['staff_flash']='Staff profile could not be saved: '.$e->getMessage();}header('Location:index.php');exit;
?>